insert into public.projects (slug, name, summary, story, status, platforms, tech, links, repo, featured, screenshots) values ('project-one', 'Project one', 'Placeholder summary. Replace with real content before launch.', 'Placeholder story. This room shows how a project is presented: what it is, who it is for, and how it was built. Replace this text with the real story, between eighty and one hundred and twenty words, before launch. Screenshots on the walls are generated placeholders and are labelled as such.', 'live', array['ios', 'macos']::text[], array['Swift', 'SwiftUI', 'CloudKit']::text[], '{"appStore":"https://apps.apple.com/app/placeholder","github":"https://github.com/alpha-studios-placeholder/project-one"}'::jsonb, 'alpha-studios-placeholder/project-one', true, '[{"src":"screens/project-one-iphone-1.png","alt":"Placeholder iPhone screenshot, first screen of Project one","device":"iphone"},{"src":"screens/project-one-mac-1.png","alt":"Placeholder Mac screenshot of Project one","device":"mac"},{"src":"screens/project-one-iphone-2.png","alt":"Placeholder iPhone screenshot, second screen of Project one","device":"iphone"}]'::jsonb) on conflict (slug) do nothing;
insert into public.projects (slug, name, summary, story, status, platforms, tech, links, repo, featured, screenshots) values ('project-two', 'Project two', 'Placeholder summary. Replace with real content before launch.', 'Placeholder story. This room shows how a project is presented: what it is, who it is for, and how it was built. Replace this text with the real story, between eighty and one hundred and twenty words, before launch. Screenshots on the walls are generated placeholders and are labelled as such.', 'beta', array['web']::text[], array['TypeScript', 'React', 'Postgres']::text[], '{"github":"https://github.com/alpha-studios-placeholder/project-two","demo":"https://example.com/placeholder-demo"}'::jsonb, 'alpha-studios-placeholder/project-two', false, '[{"src":"screens/project-two-browser-1.png","alt":"Placeholder browser screenshot, first page of Project two","device":"browser"},{"src":"screens/project-two-browser-2.png","alt":"Placeholder browser screenshot, second page of Project two","device":"browser"},{"src":"screens/project-two-iphone-1.png","alt":"Placeholder iPhone screenshot of Project two","device":"iphone"}]'::jsonb) on conflict (slug) do nothing;
